{"code": "export async function main(input: { project: string; minEvents: number }) {
  const { issues } = await sdk.sentry.listIssues({ project: input.project });
  const relevant = issues.filter(i => i.status === "unresolved" && i.count >= input.minEvents);

  // unique culprits, preserving order
  const culprits: string[] = [];
  for (const i of relevant) if (!culprits.includes(i.culprit)) culprits.push(i.culprit);

  const created: { culprit: string; sentryIssues: string[]; result: unknown }[] = [];
  const existing: { culprit: string; sentryIssues: string[]; linearIssues: string[] }[] = [];

  for (const culprit of culprits) {
    const sentryIssues = relevant.filter(i => i.culprit === culprit).map(i => i.shortId);
    const { issues: found } = await sdk.linear.searchIssues({ query: culprit });
    const matching = found.filter(l => (l.title || "").includes(culprit) || (l.description || "").includes(culprit));
    if (matching.length > 0) {
      existing.push({ culprit, sentryIssues, linearIssues: matching.map(m => m.identifier) });
    } else {
      const res = await sdk.linear.createIssue({ title: `[Sentry] ${culprit}`, description: culprit });
      created.push({ culprit, sentryIssues, result: res });
    }
  }

  return { project: input.project, relevantSentryIssues: relevant.map(i => ({ shortId: i.shortId, culprit: i.culprit, count: i.count })), existing, created };
}", "input": {"project": "api", "minEvents": 0}}

